  const api = { conjugate, table, isVerbCategory, VERBS, TEMPLATES, PERSONS: ["èo", "tu", "ello / ella", "nós", "vós", "ellos / ellas"], IMP_PERSONS: ["tu", "ello / ella", "nós", "vós", "ellos / ellas"] };
